package dev.emi.emi.network;

import net.minecraft.core.HolderLookup;
import net.minecraft.core.component.DataComponentPatch;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.NbtOps;
import net.minecraft.resources.RegistryOps;
import net.minecraft.world.item.ItemStack;

/** Component command syntax generated by the native patch codec, including removals. */
public final class NativeItemCommand {
    private NativeItemCommand() {}
    public static String argument(ItemStack stack,HolderLookup.Provider registries) {
        String item=BuiltInRegistries.ITEM.getKey(stack.getItem()).toString();
        var data=DataComponentPatch.CODEC.encodeStart(RegistryOps.create(NbtOps.INSTANCE,registries),stack.getComponentsPatch()).getOrThrow();
        if(!(data instanceof CompoundTag components) || components.isEmpty())return item;
        var parts=new java.util.ArrayList<String>();
        components.keySet().stream().sorted().forEach(key -> parts.add(key.startsWith("!")?key:key+"="+new net.minecraft.nbt.SnbtPrinterTagVisitor("",0,java.util.List.of()).visit(components.get(key))));
        return item+"["+String.join(",",parts)+"]";
    }
}
